-- Lot éditorial Spoontrotter généré par scripts/recipe-batches/build.mjs : 21 recettes, 4 nouveaux lieux.
-- Recettes rédigées pour l'application (adaptations éditoriales) à partir des compositions traditionnelles documentées.
-- Données source : data/recipe-batches/. Photos : Wikimedia Commons, vérifiées une à une (auteur et licence conservés).
-- Chargeur temporaire (pg_temp : disparaît à la fin de la session, jamais exposé à l'API).
create or replace function pg_temp.spoontrotter_import(batch jsonb) returns integer
language plpgsql as $fn$
declare
  r jsonb;
  p jsonb;
  ph jsonb;
  rid uuid;
  country_place uuid;
  place uuid;
  place_name text;
  region_text text;
  source_name constant text := 'Spoontrotter — adaptation éditoriale';
  author constant uuid := 'ac515660-4852-4ebd-8cb5-3348d60e06e9';
  total integer := 0;
begin
  for r in select value from jsonb_array_elements(batch) loop
    select id into country_place from public.culinary_places
      where country_code = r->>'country' and place_type = 'country' order by created_at limit 1;
    if country_place is null then
      raise exception 'Pays absent de l''atlas : %', r->>'country';
    end if;

    p := r->'place';
    if jsonb_typeof(p) = 'object' then
      insert into public.culinary_places (slug, name, country_code, place_type, parent_id, latitude, longitude, default_zoom, summary, is_active)
      values (p->>'slug', p->>'name', r->>'country', p->>'type', country_place, (p->>'lat')::float8, (p->>'lng')::float8,
              coalesce((p->>'zoom')::float8, case when p->>'type' = 'region' then 7 else 9 end), p->>'summary', true)
      on conflict (slug) do nothing;
      select id, name into place, place_name from public.culinary_places where slug = p->>'slug';
    elsif jsonb_typeof(p) = 'string' then
      select id, name into place, place_name from public.culinary_places where slug = p #>> '{}';
      if place is null then
        raise exception 'Lieu absent de l''atlas : %', p #>> '{}';
      end if;
    else
      place := country_place;
      place_name := null;
    end if;

    region_text := coalesce(r->>'region', place_name);
    rid := md5('spoontrotter:recipe:' || (r->>'slug'))::uuid;
    ph := r->'photo';
    if jsonb_typeof(ph) is distinct from 'object'
       or nullif(ph->>'url', '') is null or nullif(ph->>'page', '') is null
       or nullif(ph->>'license', '') is null then
      raise exception 'Photo vérifiée obligatoire pour %', r->>'slug';
    end if;
    -- Un nouveau slug ne doit pas recréer un plat déjà importé sous un autre nom.
    if exists (
      select 1 from public.recipes existing
      where existing.id <> rid and existing.country_code = r->>'country'
        and lower(regexp_replace(regexp_replace(coalesce(existing.original_title, existing.title), '\([^)]*\)', '', 'g'), '[^[:alnum:]]', '', 'g'))
          = lower(regexp_replace(regexp_replace(r->>'original', '\([^)]*\)', '', 'g'), '[^[:alnum:]]', '', 'g'))
    ) then
      raise exception 'Doublon de plat détecté pour %', r->>'slug';
    end if;

    insert into public.recipes (id, author_id, title, original_title, slug, description, excerpt, source_language, country_code, region,
      category, authenticity, status, difficulty, prep_minutes, cook_minutes, servings, published_at, primary_place_id,
      is_editorial, is_borderless, source_name, source_url, source_notes)
    values (rid, author, r->>'title', r->>'original', r->>'slug', r->>'desc', r->>'desc', 'fr', r->>'country', region_text,
      r->>'cat', coalesce(r->>'auth', 'adapted')::public.recipe_authenticity, 'published', (r->>'diff')::public.recipe_difficulty,
      (r->>'prep')::int, (r->>'cook')::int, (r->>'serv')::numeric, now(), place,
      true, false, source_name, coalesce(r->>'reference', ph->>'page'),
      'Recette éditoriale rédigée pour l’application à partir de la composition traditionnelle documentée du plat.')
    on conflict (id) do update set title = excluded.title, original_title = excluded.original_title, description = excluded.description,
      excerpt = excluded.excerpt, country_code = excluded.country_code, region = excluded.region, category = excluded.category,
      difficulty = excluded.difficulty, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes,
      servings = excluded.servings, primary_place_id = excluded.primary_place_id, source_url = excluded.source_url, updated_at = now();

    delete from public.recipe_ingredients where recipe_id = rid;
    insert into public.recipe_ingredients (recipe_id, position, name, quantity, unit, note)
    select rid, (t.o - 1)::int, t.e->>0, (t.e->>1)::numeric, t.e->>2, t.e->>3
    from jsonb_array_elements(r->'ing') with ordinality as t(e, o);

    delete from public.recipe_steps where recipe_id = rid;
    insert into public.recipe_steps (recipe_id, position, instruction)
    select rid, (t.o - 1)::int, t.s from jsonb_array_elements_text(r->'steps') with ordinality as t(s, o);

    delete from public.recipe_title_translations where recipe_id = rid;
    insert into public.recipe_title_translations (recipe_id, language_code, title, model) values
      (rid, 'fr', r->>'title', 'editorial-seed'),
      (rid, 'en', r->>'en', 'editorial-reviewed'),
      (rid, 'es', r->>'es', 'editorial-reviewed');

    delete from public.recipe_locations where recipe_id = rid;
    insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, place, 'origin', true);
    if place <> country_place then
      insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, country_place, 'origin', false);
    end if;

    delete from public.place_specialties where recipe_id = rid;
    insert into public.place_specialties (place_id, recipe_id, name, description, origin_note, is_signature, sort_order, source_name, source_url)
    values (place, rid, r->>'original', r->>'desc', coalesce(region_text, (select name from public.culinary_places where id = country_place)),
            place <> country_place, 10, source_name, ph->>'page');

    delete from public.recipe_images where recipe_id = rid and source_type = 'external_licensed';
    if jsonb_typeof(ph) = 'object' then
      insert into public.recipe_images (recipe_id, source_type, status, external_url, alt_text, source_name, source_page_url,
        photographer_name, license_name, license_url, attribution_text, is_primary, is_representative, moderation_notes)
      values (rid, 'external_licensed', 'ready', ph->>'url', r->>'title', coalesce(ph->>'source', 'Wikimedia Commons'), ph->>'page',
        nullif(ph->>'author', ''), ph->>'license', nullif(ph->>'licenseUrl', ''),
        'Photo : ' || coalesce(nullif(ph->>'author', ''), 'auteur inconnu') || ' · ' || (ph->>'license') || ' · ' || coalesce(ph->>'source', 'Wikimedia Commons'),
        true, true, 'Photo libre vérifiée à l’œil : le fichier représente ce plat.');
    end if;

    total := total + 1;
  end loop;
  return total;
end;
$fn$;
select pg_temp.spoontrotter_import($batch$[{"slug":"blanquette-de-veau","country":"FR","original":"Blanquette de veau","title":"Blanquette de veau à l’ancienne (sauce crème et champignons)","en":"Blanquette de veau (veal in creamy white sauce)","es":"Blanquette de ternera (en salsa blanca cremosa)","desc":"Plat bourgeois français : veau poché sans coloration avec carottes et oignon piqué, puis nappé d’une sauce liée au roux, à la crème et au jaune d’œuf, avec champignons et petits oignons; servi avec du riz.","cat":"Plat principal","diff":"medium","prep":30,"cook":120,"serv":6,"reference":"https://fr.wikipedia.org/wiki/Blanquette_de_veau","ing":[["Veau (tendron, épaule, flanchet)",1.5,"kg","en morceaux"],["Carottes",3,null,"en tronçons"],["Oignon",1,null,"piqué de 2 clous de girofle"],["Poireau",1,null,"le blanc"],["Bouquet garni",1,null,null],["Champignons de Paris",250,"g",null],["Petits oignons grelots",12,null,null],["Beurre",50,"g",null],["Farine",40,"g",null],["Crème fraîche épaisse",200,"ml",null],["Jaune d’œuf",1,null,null],["Citron",0.5,null,"jus"],["Sel et poivre blanc",1,"c. à thé",null],["Riz blanc",300,"g","pour servir"]],"steps":["Mettre le veau dans une cocotte, couvrir d’eau froide, porter à ébullition et écumer soigneusement.","Ajouter carottes, oignon piqué, poireau, bouquet garni, sel et poivre, puis cuire 1 h 30 à petit frémissement.","Pendant ce temps, cuire les champignons et les petits oignons à couvert avec un peu de beurre et de bouillon.","Préparer un roux blanc avec le reste du beurre et la farine, puis le mouiller avec 750 ml de bouillon filtré en fouettant; cuire 10 minutes.","Hors du feu, lier la sauce avec la crème mélangée au jaune d’œuf et au jus de citron, sans faire bouillir.","Ajouter la viande, les carottes, les champignons et les oignons, réchauffer doucement et servir avec le riz."],"photo":{"file":"File:Blanquette de veau.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/3/3f/Blanquette_de_veau.jpg","page":"https://commons.wikimedia.org/wiki/File:Blanquette_de_veau.jpg","author":"Magali Kunstmann-Pelchat","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/"}},{"slug":"mousse-au-chocolat","country":"FR","original":"Mousse au chocolat","title":"Mousse au chocolat (chocolat noir et blancs en neige)","en":"Chocolate mousse","es":"Mousse de chocolate","desc":"Dessert classique français : chocolat noir fondu avec un peu de beurre, enrichi de jaunes d’œufs puis allégé de blancs montés en neige ferme, et pris au froid.","cat":"Dessert","diff":"easy","prep":20,"cook":5,"serv":6,"reference":"https://fr.wikipedia.org/wiki/Mousse_au_chocolat","ing":[["Chocolat noir 60–70 %",200,"g",null],["Beurre",30,"g",null],["Œufs",6,null,"blancs et jaunes séparés"],["Sucre",30,"g",null],["Sel",1,"pincée",null]],"steps":["Faire fondre le chocolat avec le beurre au bain-marie, puis laisser tiédir.","Incorporer les jaunes d’œufs un à un au chocolat tiède.","Monter les blancs en neige avec le sel, puis ajouter le sucre et fouetter jusqu’à ce qu’ils soient fermes et brillants.","Incorporer un tiers des blancs au chocolat en remuant vivement, puis le reste délicatement à la spatule.","Répartir dans des verrines ou un saladier et réfrigérer au moins 4 heures."],"photo":{"file":"File:Mousse au chocolat (31043136424).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/9/9b/Mousse_au_chocolat_%2831043136424%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Mousse_au_chocolat_(31043136424).jpg","author":"Theo Crazzolara","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0"}},{"slug":"galette-des-rois","country":"FR","original":"Galette des rois","title":"Galette des rois à la frangipane","en":"Galette des rois (puff pastry king cake with frangipane)","es":"Galette des rois (roscón de hojaldre con frangipane)","desc":"Gâteau de l’Épiphanie dans la moitié nord de la France : deux disques de pâte feuilletée renfermant une frangipane aux amandes et une fève, rayés et dorés au four.","cat":"Dessert","diff":"medium","prep":30,"cook":35,"serv":8,"reference":"https://fr.wikipedia.org/wiki/Galette_des_rois","ing":[["Pâte feuilletée pur beurre",2,"disques","de 28 cm"],["Poudre d’amandes",125,"g",null],["Sucre",100,"g",null],["Beurre mou",100,"g",null],["Œufs",2,null,null],["Crème pâtissière",100,"g","facultatif"],["Rhum",1,"c. à soupe","facultatif"],["Jaune d’œuf",1,null,"pour la dorure"],["Fève",1,null,null]],"steps":["Préparer la crème d’amandes : battre le beurre mou avec le sucre, ajouter les œufs, la poudre d’amandes, le rhum et éventuellement la crème pâtissière pour une frangipane.","Étaler la frangipane sur un disque de pâte en laissant 2 cm de bord, et y glisser la fève.","Mouiller le bord, couvrir du second disque et souder en pressant; chiqueter le pourtour.","Dorer au jaune d’œuf, réfrigérer 30 minutes, dorer à nouveau puis dessiner des rayures à la pointe du couteau.","Cuire 35 minutes à 190 °C jusqu’à ce que la galette soit bien gonflée et dorée; servir tiède."],"photo":{"file":"File:Part de galette des rois 2013.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/a/a0/Part_de_galette_des_rois_2013.jpg","page":"https://commons.wikimedia.org/wiki/File:Part_de_galette_des_rois_2013.jpg","author":"Lionel Allorge","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"}},{"slug":"petit-sale-aux-lentilles","country":"FR","original":"Petit salé aux lentilles","title":"Petit salé aux lentilles (porc demi-sel et lentilles vertes)","en":"Petit salé aux lentilles (salt pork with green lentils)","es":"Petit salé con lentejas (cerdo en salazón con lentejas verdes)","desc":"Plat de bistrot : poitrine, palette et saucisse de porc demi-sel mijotées avec des lentilles vertes, carottes, oignon et bouquet garni.","cat":"Plat principal","diff":"easy","prep":20,"cook":120,"serv":6,"reference":"https://fr.wikipedia.org/wiki/Petit_salé_aux_lentilles","ing":[["Petit salé (poitrine et palette demi-sel)",1.2,"kg","dessalé"],["Saucisses fumées",2,null,"facultatif"],["Lentilles vertes",400,"g",null],["Carottes",3,null,"en rondelles"],["Oignons",2,null,"dont 1 piqué de clous de girofle"],["Bouquet garni",1,null,null],["Ail",2,"gousses",null],["Poivre",1,"c. à thé",null]],"steps":["Dessaler le petit salé 2 heures dans l’eau froide, puis le blanchir 10 minutes et égoutter.","Le remettre dans une cocotte avec l’oignon piqué, le bouquet garni et le poivre; couvrir d’eau et cuire 1 heure à frémissement.","Ajouter les lentilles rincées, les carottes, l’autre oignon émincé et l’ail, et les saucisses.","Poursuivre la cuisson 40 minutes jusqu’à ce que les lentilles soient tendres sans éclater.","Goûter avant de saler, couper les viandes et servir avec les lentilles."],"photo":{"file":"File:Petit salé 02.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/3/3d/Petit_sal%C3%A9_02.jpg","page":"https://commons.wikimedia.org/wiki/File:Petit_sal%C3%A9_02.jpg","author":"Arnaud 25","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"calissons-d-aix","country":"FR","place":{"slug":"fr-aix-en-provence","name":"Aix-en-Provence","type":"city","lat":43.5297,"lng":5.4474,"summary":"Ville des Bouches-du-Rhône, patrie des calissons au melon confit et aux amandes."},"original":"Calissons d’Aix","title":"Calissons d’Aix (pâte d’amandes au melon confit et glace royale)","en":"Calissons d’Aix (almond and candied melon confection)","es":"Calissons de Aix (dulce de almendra y melón confitado)","desc":"Confiserie d’Aix-en-Provence en forme de navette : pâte d’amandes et de melon confit posée sur une feuille d’azyme et recouverte d’une fine couche de glace royale.","cat":"Dessert","diff":"hard","prep":60,"cook":10,"serv":30,"reference":"https://fr.wikipedia.org/wiki/Calisson","ing":[["Amandes émondées",250,"g",null],["Melon confit",200,"g",null],["Écorce d’orange confite",30,"g",null],["Sucre glace",250,"g",null],["Eau de fleur d’oranger",1,"c. à soupe",null],["Papier azyme",2,"feuilles",null],["Blanc d’œuf",1,null,"pour la glace royale"],["Sucre glace (glace royale)",150,"g",null],["Jus de citron",0.5,"c. à thé",null]],"steps":["Mixer finement les amandes avec le sucre glace, puis ajouter le melon et l’orange confits et la fleur d’oranger jusqu’à obtenir une pâte homogène.","Chauffer la pâte 5 minutes à feu doux en remuant pour la dessécher légèrement, puis laisser tiédir.","Étaler la pâte sur 1 cm d’épaisseur sur le papier azyme et laisser reposer une nuit.","Fouetter le blanc d’œuf avec le sucre glace et le citron pour obtenir une glace royale épaisse, puis en napper finement la pâte.","Découper en navettes à l’emporte-pièce et sécher 10 minutes au four à 100 °C, porte entrouverte."],"photo":{"file":"File:Calissons de Provence à Châteauneuf-du-Pape.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/4/4e/Calissons_de_Provence_%C3%A0_Ch%C3%A2teauneuf-du-Pape.jpg","page":"https://commons.wikimedia.org/wiki/File:Calissons_de_Provence_%C3%A0_Ch%C3%A2teauneuf-du-Pape.jpg","author":"jean-louis zimmermann","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0"}},{"slug":"pate-en-croute","country":"FR","original":"Pâté en croûte","title":"Pâté en croûte (farce de porc et volaille, gelée et pâte dorée)","en":"Pâté en croûte (French meat pie in pastry)","es":"Pâté en croûte (paté de carne en costra de masa)","desc":"Pièce de charcuterie française : farce de porc, veau et volaille marinée au cognac, avec cœur de foie gras ou de volaille, cuite dans une pâte brisée moulée puis comblée de gelée et servie froide en tranches.","cat":"Entrée","diff":"hard","prep":90,"cook":90,"serv":12,"reference":"https://fr.wikipedia.org/wiki/Pâté_en_croûte","ing":[["Pâte brisée ou à pâté",800,"g",null],["Échine de porc",500,"g","hachée"],["Gorge ou lard gras",200,"g","haché"],["Épaule de veau",300,"g","hachée"],["Filets de volaille",300,"g","en lanières"],["Foie gras ou foies de volaille",150,"g","facultatif"],["Cognac",50,"ml",null],["Échalotes",2,null,"ciselées"],["Pistaches",40,"g",null],["Sel",18,"g",null],["Poivre et quatre-épices",1,"c. à thé",null],["Gelée au madère",300,"ml","tiède"],["Jaune d’œuf",1,null,"pour la dorure"]],"steps":["Mariner une nuit les viandes hachées et les lanières de volaille avec le cognac, les échalotes, le sel, le poivre et les épices.","Foncer un moule à pâté avec les deux tiers de la pâte, en laissant déborder.","Remplir en alternant farce, lanières de volaille, foie et pistaches, en tassant bien.","Couvrir d’un couvercle de pâte, souder, faire deux cheminées et dorer; cuire 20 minutes à 210 °C puis 1 heure à 170 °C.","Laisser tiédir, couler la gelée tiède par les cheminées et réfrigérer 24 heures avant de trancher."],"photo":{"file":"File:Pâté en Croûte.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/c/ce/P%C3%A2t%C3%A9_en_Cro%C3%BBte.jpg","page":"https://commons.wikimedia.org/wiki/File:P%C3%A2t%C3%A9_en_Cro%C3%BBte.jpg","author":"ZhengZhou","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"baba-au-rhum","country":"FR","place":"fr-lorraine","original":"Baba au rhum","title":"Baba au rhum (brioche imbibée de sirop au rhum et chantilly)","en":"Rum baba","es":"Babá al ron","desc":"Pâtisserie née à la cour du roi Stanislas en Lorraine et popularisée à Paris par Stohrer : brioche légère imbibée d’un sirop au rhum, servie avec de la crème chantilly.","cat":"Dessert","diff":"medium","prep":40,"cook":25,"serv":8,"reference":"https://fr.wikipedia.org/wiki/Baba_au_rhum","ing":[["Farine",250,"g",null],["Levure boulangère fraîche",15,"g",null],["Œufs",4,null,null],["Beurre mou",80,"g",null],["Sucre",20,"g","pour la pâte"],["Sel",1,"pincée",null],["Lait tiède",50,"ml",null],["Eau (sirop)",750,"ml",null],["Sucre (sirop)",350,"g",null],["Rhum ambré",150,"ml",null],["Crème liquide entière",300,"ml","pour la chantilly"]],"steps":["Délayer la levure dans le lait tiède, puis la pétrir avec la farine, le sucre, le sel et les œufs jusqu’à obtenir une pâte élastique; incorporer le beurre mou.","Remplir à moitié des moules à baba beurrés et laisser lever 1 heure jusqu’au bord.","Cuire 20 à 25 minutes à 180 °C, démouler et laisser sécher quelques heures.","Porter l’eau et le sucre à ébullition, retirer du feu et ajouter le rhum.","Plonger les babas dans le sirop chaud jusqu’à ce qu’ils soient bien imbibés, puis servir avec la chantilly et un trait de rhum."],"photo":{"file":"File:Baba au rhum (Brasserie Mollard).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/0/06/Baba_au_rhum_%28Brasserie_Mollard%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Baba_au_rhum_(Brasserie_Mollard).jpg","author":"Tangopaso","license":"Public domain","licenseUrl":null}},{"slug":"magret-de-canard","country":"FR","place":"fr-gascogne","original":"Magret de canard","title":"Magret de canard poêlé (peau croustillante, chair rosée)","en":"Pan-seared duck magret","es":"Magret de pato a la sartén","desc":"Filet de canard gras du Sud-Ouest, quadrillé côté peau et cuit d’abord sur la graisse jusqu’à ce qu’elle soit croustillante, puis à peine saisi côté chair pour rester rosé.","cat":"Plat principal","diff":"easy","prep":10,"cook":20,"serv":2,"reference":"https://fr.wikipedia.org/wiki/Magret","ing":[["Magret de canard",1,null,"environ 400 g"],["Fleur de sel",1,"c. à thé",null],["Poivre noir",0.5,"c. à thé",null],["Miel",1,"c. à soupe","facultatif"],["Vinaigre balsamique ou fond de veau",2,"c. à soupe","pour déglacer"],["Pommes de terre",400,"g","sautées dans la graisse, pour servir"]],"steps":["Sortir le magret 30 minutes avant, entailler la peau en quadrillage sans toucher la chair.","Le poser côté peau dans une poêle froide et cuire 8 à 10 minutes à feu moyen en retirant la graisse au fur et à mesure.","Retourner et cuire 3 à 4 minutes côté chair pour une cuisson rosée.","Laisser reposer 5 minutes sous papier aluminium, puis trancher en biais.","Déglacer la poêle au miel et au balsamique, napper les tranches, assaisonner de fleur de sel et de poivre, et servir avec des pommes de terre sautées."],"photo":{"file":"File:Magret de canard 01.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/0/0c/Magret_de_canard_01.jpg","page":"https://commons.wikimedia.org/wiki/File:Magret_de_canard_01.jpg","author":"Arnaud 25","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"pieds-paquets-marseillais","country":"FR","place":"fr-marseille","original":"Pieds paquets","title":"Pieds paquets marseillais (paquets de tripes d’agneau et pieds en sauce)","en":"Marseille pieds paquets (lamb tripe parcels and trotters)","es":"Pieds paquets marselleses (paquetes de callos y patas de cordero)","desc":"Spécialité de Marseille et de Sisteron : petits paquets de panse d’agneau farcis au petit salé et à l’ail, mijotés très longuement avec des pieds d’agneau dans une sauce au vin blanc et à la tomate.","cat":"Plat principal","diff":"hard","prep":60,"cook":420,"serv":6,"reference":"https://fr.wikipedia.org/wiki/Pieds_paquets","ing":[["Panse d’agneau blanchie",1,"kg","coupée en carrés de 10 cm"],["Pieds d’agneau",6,null,"blanchis"],["Petit salé",200,"g","haché"],["Ail",6,"gousses","hachées"],["Persil",1,"bouquet","haché"],["Oignons",2,null,"émincés"],["Carottes",2,null,"en rondelles"],["Tomates concassées",400,"g",null],["Vin blanc sec",500,"ml",null],["Huile d’olive",3,"c. à soupe",null],["Bouquet garni",1,null,null],["Sel et poivre",1,"c. à thé",null]],"steps":["Mélanger le petit salé, la moitié de l’ail et le persil; déposer un peu de farce sur chaque carré de panse, replier et fermer en faisant une incision où glisser une pointe.","Faire revenir les oignons et les carottes dans l’huile d’olive, ajouter le reste de l’ail et les tomates.","Ajouter les paquets et les pieds, mouiller avec le vin blanc et de l’eau à hauteur, ajouter le bouquet garni.","Couvrir et cuire au moins 7 heures à feu très doux ou au four à 130 °C.","Rectifier l’assaisonnement et servir très chaud avec des pommes de terre vapeur."],"photo":{"file":"File:Pieds paquets de Marseille avec une pomme de terre.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/b/b8/Pieds_paquets_de_Marseille_avec_une_pomme_de_terre.jpg","page":"https://commons.wikimedia.org/wiki/File:Pieds_paquets_de_Marseille_avec_une_pomme_de_terre.jpg","author":"Romainbehar","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en"}},{"slug":"panisses-marseillaises","country":"FR","place":"fr-marseille","original":"Panisses","title":"Panisses marseillaises (bâtonnets de farine de pois chiches frits)","en":"Marseille panisses (fried chickpea flour sticks)","es":"Panisses marselleses (bastones fritos de harina de garbanzo)","desc":"Spécialité de l’Estaque : bouillie de farine de pois chiches à l’huile d’olive, coulée et refroidie, puis coupée en bâtonnets et frite jusqu’à ce qu’elle soit croustillante dehors et fondante dedans.","cat":"Street food","diff":"easy","prep":20,"cook":30,"serv":6,"reference":"https://fr.wikipedia.org/wiki/Panisse","ing":[["Farine de pois chiches",250,"g",null],["Eau",1,"l",null],["Huile d’olive",2,"c. à soupe",null],["Sel",1,"c. à thé",null],["Poivre",0.5,"c. à thé",null],["Huile de friture",500,"ml",null]],"steps":["Délayer la farine de pois chiches dans un quart de l’eau froide pour éviter les grumeaux.","Porter le reste de l’eau à ébullition avec l’huile d’olive et le sel, verser la farine délayée et cuire 10 minutes en remuant sans cesse.","Verser dans des moules ou des tasses huilés et laisser refroidir plusieurs heures.","Démouler et couper en bâtonnets ou en rondelles.","Frire dans l’huile chaude jusqu’à ce qu’ils soient dorés, égoutter et servir salés et poivrés."],"photo":{"file":"File:Panisses frits à l'huile d'olive.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/1/11/Panisses_frits_%C3%A0_l%27huile_d%27olive.jpg","page":"https://commons.wikimedia.org/wiki/File:Panisses_frits_%C3%A0_l%27huile_d%27olive.jpg","author":"Mon Œil","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0"}},{"slug":"farci-poitevin","country":"FR","place":"fr-poitou","original":"Farci poitevin","title":"Farci poitevin (pain d’herbes et de lard cuit dans le bouillon)","en":"Farci poitevin (Poitou green vegetable and bacon loaf)","es":"Farci poitevin (pastel de hierbas y tocino del Poitou)","desc":"Plat paysan du Poitou : chou vert, oseille, blettes et herbes hachées avec du lard et des œufs, enfermés dans des feuilles de chou et pochés dans un bouillon, servis tièdes ou froids en tranches.","cat":"Plat principal","diff":"medium","prep":45,"cook":150,"serv":8,"reference":"https://fr.wikipedia.org/wiki/Farci_poitevin","ing":[["Chou vert",1,null,"grandes feuilles réservées"],["Feuilles de blettes",300,"g",null],["Oseille",150,"g",null],["Épinards",200,"g",null],["Poireau",1,null,null],["Lard gras ou poitrine",250,"g","haché"],["Œufs",4,null,null],["Mie de pain",100,"g","trempée dans du lait"],["Ail",3,"gousses",null],["Persil et ciboulette",1,"bouquet",null],["Sel et poivre",1,"c. à thé",null],["Bouillon de pot-au-feu",3,"l",null]],"steps":["Blanchir 3 minutes les grandes feuilles de chou et les étaler en croix dans un filet ou un torchon.","Hacher le reste du chou, les blettes, l’oseille, les épinards, le poireau, l’ail et les herbes.","Mélanger ces verdures avec le lard, les œufs et la mie de pain essorée; saler et poivrer.","Déposer la farce sur les feuilles de chou, refermer en boule et serrer le filet.","Pocher 2 h 30 dans le bouillon frémissant, égoutter et servir tiède ou froid en tranches."],"photo":{"file":"File:Farci Poitevin.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/2/2b/Farci_Poitevin.JPG","page":"https://commons.wikimedia.org/wiki/File:Farci_Poitevin.JPG","author":"Nikoniste","license":"Public domain","licenseUrl":null}},{"slug":"carbonade-flamande","country":"FR","place":"fr-flandre","original":"Carbonade flamande","title":"Carbonade flamande (bœuf braisé à la bière et au pain d’épices)","en":"Carbonade flamande (Flemish beef and beer stew)","es":"Carbonade flamande (estofado de ternera a la cerveza)","desc":"Plat de la Flandre française et belge : bœuf braisé avec beaucoup d’oignons dans la bière brune, lié au pain d’épices tartiné de moutarde et adouci à la cassonade, servi avec des frites.","cat":"Plat principal","diff":"medium","prep":30,"cook":180,"serv":6,"reference":"https://fr.wikipedia.org/wiki/Carbonade_flamande","ing":[["Bœuf à braiser (paleron, joue)",1.5,"kg","en morceaux"],["Oignons",4,null,"émincés"],["Bière brune ou ambrée",750,"ml",null],["Pain d’épices",3,"tranches",null],["Moutarde",2,"c. à soupe",null],["Cassonade",2,"c. à soupe",null],["Vinaigre de cidre",1,"c. à soupe",null],["Beurre ou saindoux",40,"g",null],["Thym et laurier",1,"bouquet",null],["Sel et poivre",1,"c. à thé",null]],"steps":["Faire dorer la viande en plusieurs fois dans le beurre, saler, poivrer et réserver.","Faire fondre les oignons dans la même cocotte, saupoudrer de cassonade et laisser caraméliser légèrement.","Remettre la viande, mouiller avec la bière, ajouter le thym, le laurier et le vinaigre.","Tartiner le pain d’épices de moutarde et le poser sur le dessus, côté moutarde vers le bas.","Couvrir et mijoter 3 heures à feu doux en remuant de temps en temps; servir avec des frites."],"photo":{"file":"File:Jielbeaumadier carbonade flamande 2010.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/8/82/Jielbeaumadier_carbonade_flamande_2010.jpg","page":"https://commons.wikimedia.org/wiki/File:Jielbeaumadier_carbonade_flamande_2010.jpg","author":"Jiel Beaumadier","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"tarte-aux-mirabelles","country":"FR","place":"fr-lorraine","original":"Tarte aux mirabelles","title":"Tarte aux mirabelles de Lorraine","en":"Lorraine mirabelle plum tart","es":"Tarta de ciruelas mirabel de Lorena","desc":"Tarte de fin d’été en Lorraine : pâte brisée garnie de mirabelles dénoyautées serrées, parfois avec une fine migaine d’œufs et de crème, saupoudrée de sucre et dorée au four.","cat":"Dessert","diff":"easy","prep":25,"cook":40,"serv":8,"reference":"https://fr.wikipedia.org/wiki/Mirabelle_de_Lorraine","ing":[["Pâte brisée",1,null,"pour un moule de 28 cm"],["Mirabelles",800,"g","dénoyautées"],["Poudre d’amandes ou semoule",2,"c. à soupe","pour absorber le jus"],["Sucre",80,"g",null],["Œufs",2,null,"pour la migaine, facultatif"],["Crème fraîche",150,"ml","pour la migaine, facultatif"]],"steps":["Préchauffer le four à 200 °C et foncer le moule avec la pâte; piquer le fond.","Saupoudrer le fond de poudre d’amandes ou de semoule.","Disposer les mirabelles bien serrées, face coupée vers le haut, et les saupoudrer de la moitié du sucre.","Si désiré, battre les œufs avec la crème et le reste du sucre et verser entre les fruits.","Cuire 35 à 40 minutes jusqu’à ce que la pâte soit dorée et les fruits caramélisés; servir tiède."],"photo":{"file":"File:Tarte aux mirabelles.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/0/06/Tarte_aux_mirabelles.jpg","page":"https://commons.wikimedia.org/wiki/File:Tarte_aux_mirabelles.jpg","author":"Richieman","license":"Public domain","licenseUrl":null}},{"slug":"saucisse-de-morteau-aux-lentilles","country":"FR","place":{"slug":"fr-morteau","name":"Morteau","type":"locality","lat":47.0573,"lng":6.6066,"summary":"Ville du Haut-Doubs, en Franche-Comté, dont la saucisse est fumée dans les tuyés."},"original":"Saucisse de Morteau aux lentilles","title":"Saucisse de Morteau aux lentilles (saucisse fumée du Haut-Doubs)","en":"Morteau sausage with lentils","es":"Salchicha de Morteau con lentejas","desc":"Plat de Franche-Comté : saucisse de Morteau fumée au bois de résineux dans les tuyés, pochée doucement puis servie sur des lentilles vertes mijotées avec carottes et lardons.","cat":"Plat principal","diff":"easy","prep":20,"cook":50,"serv":4,"reference":"https://fr.wikipedia.org/wiki/Saucisse_de_Morteau","ing":[["Saucisses de Morteau",2,null,null],["Lentilles vertes",350,"g",null],["Carottes",2,null,"en dés"],["Oignon",1,null,"haché"],["Lardons fumés",100,"g",null],["Poireau",1,null,"en rondelles"],["Bouquet garni",1,null,null],["Vin blanc du Jura",150,"ml","facultatif"],["Poivre",0.5,"c. à thé",null]],"steps":["Piquer les saucisses et les plonger dans une casserole d’eau froide; porter à frémissement sans bouillir et cuire 40 minutes.","Pendant ce temps, faire revenir les lardons, l’oignon, les carottes et le poireau dans une cocotte.","Ajouter les lentilles rincées, le bouquet garni, le vin blanc et de l’eau à hauteur; cuire 25 minutes.","Ajouter les saucisses entières sur les lentilles 10 minutes avant la fin pour qu’elles les parfument.","Trancher les saucisses et servir sur les lentilles, en goûtant avant de saler."],"photo":{"file":"File:Saucisse de Morteau aux lentilles.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/4/41/Saucisse_de_Morteau_aux_lentilles.jpg","page":"https://commons.wikimedia.org/wiki/File:Saucisse_de_Morteau_aux_lentilles.jpg","author":"Randalfino","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0"}},{"slug":"diots-au-vin-blanc","country":"FR","place":"fr-savoie","original":"Diots au vin blanc","title":"Diots de Savoie au vin blanc (saucisses mijotées aux oignons)","en":"Savoy diots in white wine","es":"Diots de Saboya al vino blanco","desc":"Plat savoyard : petites saucisses de porc (diots) dorées puis mijotées avec des oignons dans le vin blanc de Savoie, servies avec des crozets, de la polenta ou des pommes de terre.","cat":"Plat principal","diff":"easy","prep":15,"cook":45,"serv":4,"reference":"https://fr.wikipedia.org/wiki/Diot","ing":[["Diots de Savoie",8,null,null],["Oignons",3,null,"émincés"],["Vin blanc de Savoie",500,"ml",null],["Beurre",20,"g",null],["Laurier",2,"feuilles",null],["Thym",2,"branches",null],["Poivre",0.5,"c. à thé",null]],"steps":["Piquer les diots et les faire dorer sur toutes les faces dans le beurre; réserver.","Faire fondre les oignons dans la même cocotte jusqu’à ce qu’ils soient blonds.","Remettre les diots, verser le vin blanc, ajouter laurier, thym et poivre.","Couvrir et laisser mijoter 35 à 40 minutes à feu doux; la sauce doit réduire de moitié.","Servir avec des crozets, de la polenta ou des pommes de terre vapeur."],"photo":{"file":"File:Diots au vin blanc.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/a/a4/Diots_au_vin_blanc.jpg","page":"https://commons.wikimedia.org/wiki/File:Diots_au_vin_blanc.jpg","author":"Javi Vte Rejas","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0"}},{"slug":"pastis-landais","country":"FR","place":{"slug":"fr-landes","name":"Landes","type":"region","lat":43.95,"lng":-0.75,"summary":"Département forestier de Gascogne, entre océan et Chalosse : pastis landais, canard et asperges."},"original":"Pastis landais","title":"Pastis landais (brioche parfumée à l’anis, au rhum et à la fleur d’oranger)","en":"Pastis landais (anise and rum scented brioche)","es":"Pastis landais (brioche aromatizado con anís, ron y azahar)","desc":"Gâteau brioché des Landes servi aux fêtes : pâte levée riche en œufs et en beurre, parfumée à l’anis, au rhum, à la vanille et à la fleur d’oranger, cuite dans un grand moule et parsemée de sucre.","cat":"Dessert","diff":"medium","prep":40,"cook":40,"serv":10,"reference":"https://fr.wikipedia.org/wiki/Pastis_landais","ing":[["Farine",500,"g",null],["Levure boulangère fraîche",20,"g",null],["Œufs",5,null,null],["Sucre",150,"g",null],["Beurre fondu",125,"g",null],["Lait tiède",100,"ml",null],["Rhum",3,"c. à soupe",null],["Pastis ou anisette",2,"c. à soupe",null],["Eau de fleur d’oranger",2,"c. à soupe",null],["Vanille",1,"gousse",null],["Sucre en grains",2,"c. à soupe","pour le dessus"]],"steps":["La veille, faire macérer le rhum, le pastis, la fleur d’oranger et la vanille grattée.","Délayer la levure dans le lait tiède, puis mélanger avec la farine, le sucre, les œufs, le beurre fondu et les parfums; pétrir 10 minutes.","Laisser lever 3 heures, ou une nuit au frais, jusqu’à ce que la pâte double.","Dégazer, mettre dans un grand moule beurré, laisser lever encore 1 heure et parsemer de sucre en grains.","Cuire 40 minutes à 170 °C jusqu’à ce que le pastis soit bien doré."],"photo":{"file":"File:Pastis landais.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/7/79/Pastis_landais.JPG","page":"https://commons.wikimedia.org/wiki/File:Pastis_landais.JPG","author":"Jibi44","license":"CC BY-SA 2.5","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.5"}},{"slug":"tarte-aux-pralines","country":"FR","place":"fr-lyon","original":"Tarte aux pralines","title":"Tarte aux pralines lyonnaise (pralines roses fondues à la crème)","en":"Lyon pink praline tart","es":"Tarta de pralinés rosas de Lyon","desc":"Dessert emblématique de Lyon : fond de pâte sucrée garni de pralines roses concassées fondues dans la crème, qui forment en refroidissant une garniture rose vif et fondante.","cat":"Dessert","diff":"easy","prep":20,"cook":35,"serv":8,"reference":"https://fr.wikipedia.org/wiki/Tarte_aux_pralines","ing":[["Pâte sucrée",1,null,"pour un moule de 24 cm"],["Pralines roses",250,"g","concassées"],["Crème liquide entière",250,"ml",null]],"steps":["Foncer le moule avec la pâte sucrée et la cuire à blanc 15 minutes à 180 °C.","Porter la crème à ébullition avec les pralines concassées et laisser frémir 5 à 10 minutes en remuant, jusqu’à ce que le mélange nappe la cuillère.","Verser l’appareil rose dans le fond de tarte.","Remettre au four 10 minutes pour faire légèrement bouillonner la garniture.","Laisser refroidir complètement pour que la garniture prenne, puis servir à température ambiante."],"photo":{"file":"File:Une part de tarte aux pralines.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/1/18/Une_part_de_tarte_aux_pralines.jpg","page":"https://commons.wikimedia.org/wiki/File:Une_part_de_tarte_aux_pralines.jpg","author":"Benoît Prieur","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en"}},{"slug":"ttoro-saint-jean-de-luz","country":"FR","place":"fr-pays-basque","original":"Ttoro","title":"Ttoro basque (soupe de poissons et fruits de mer au piment d’Espelette)","en":"Basque ttoro (fish and shellfish soup)","es":"Ttoro vasco (sopa de pescados y mariscos)","desc":"Soupe des pêcheurs de Saint-Jean-de-Luz : morceaux de merlu, de lotte et de grondin, langoustines et moules cuits dans un bouillon de têtes de poisson à la tomate, au vin blanc et au piment d’Espelette.","cat":"Soupe","diff":"medium","prep":40,"cook":60,"serv":6,"reference":"https://fr.wikipedia.org/wiki/Ttoro","ing":[["Têtes et arêtes de poisson",1,"kg","pour le bouillon"],["Merlu",500,"g","en tronçons"],["Lotte",400,"g","en morceaux"],["Langoustines",12,null,null],["Moules",1,"kg","nettoyées"],["Oignons",2,null,"émincés"],["Tomates",4,null,"concassées"],["Ail",4,"gousses",null],["Vin blanc sec",250,"ml",null],["Piment d’Espelette",1,"c. à thé",null],["Huile d’olive",4,"c. à soupe",null],["Farine",2,"c. à soupe","pour fariner le poisson"],["Pain grillé frotté d’ail",6,"tranches","pour servir"]],"steps":["Préparer un bouillon avec les têtes et arêtes, un oignon, de l’eau, le vin blanc et le piment; cuire 30 minutes puis filtrer.","Faire revenir l’autre oignon, l’ail et les tomates dans l’huile d’olive, puis ajouter le bouillon filtré et réduire 15 minutes.","Fariner les morceaux de merlu et de lotte et les dorer rapidement à la poêle.","Ajouter les poissons, les langoustines et les moules dans le bouillon et cuire 8 minutes jusqu’à ce que les moules s’ouvrent.","Servir dans des assiettes creuses sur des tranches de pain grillé frotté d’ail."],"photo":{"file":"File:Ttoro.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/5/52/Ttoro.jpg","page":"https://commons.wikimedia.org/wiki/File:Ttoro.jpg","author":"Arnaud 25","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"cotriade-bretonne","country":"FR","place":"fr-bretagne","original":"Cotriade","title":"Cotriade bretonne (soupe de poissons et pommes de terre)","en":"Breton cotriade (fish and potato stew)","es":"Cotriade bretona (guiso de pescado y patatas)","desc":"Plat des marins bretons : poissons de la pêche du jour et coquillages cuits sur un lit de pommes de terre et d’oignons, le bouillon servi d’abord sur du pain, le poisson ensuite avec une vinaigrette.","cat":"Soupe","diff":"easy","prep":30,"cook":40,"serv":6,"reference":"https://fr.wikipedia.org/wiki/Cotriade","ing":[["Poissons variés (maquereau, merlan, lieu, congre)",1.5,"kg","en tronçons"],["Moules",500,"g","nettoyées"],["Crevettes ou langoustines",300,"g",null],["Pommes de terre",1,"kg","en quartiers"],["Oignons",3,null,"émincés"],["Beurre demi-sel",50,"g",null],["Bouquet garni",1,null,null],["Eau",2,"l",null],["Sel et poivre",1,"c. à thé",null],["Vinaigrette à l’échalote",100,"ml","pour servir"],["Pain de campagne",6,"tranches",null]],"steps":["Faire fondre les oignons dans le beurre demi-sel sans les colorer.","Ajouter l’eau, les pommes de terre, le bouquet garni, saler et poivrer; cuire 15 minutes.","Ajouter les poissons à chair ferme, puis 5 minutes plus tard les poissons fragiles, les crustacés et les moules; cuire encore 8 minutes.","Servir d’abord le bouillon versé sur des tranches de pain.","Présenter ensuite poissons, coquillages et pommes de terre avec la vinaigrette à l’échalote."],"photo":{"file":"File:Cotriade.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/2/2d/Cotriade.jpg","page":"https://commons.wikimedia.org/wiki/File:Cotriade.jpg","author":"Arnaud 25","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"brioche-vendeenne","country":"FR","place":{"slug":"fr-vendee","name":"Vendée","type":"region","lat":46.67,"lng":-1.43,"summary":"Département atlantique des Pays de la Loire : brioche vendéenne, préfou, mogettes et jambon de Vendée."},"original":"Brioche vendéenne","title":"Brioche vendéenne tressée (fleur d’oranger et eau-de-vie)","en":"Vendée brioche","es":"Brioche de la Vendée (trenzado)","desc":"Brioche tressée de Vendée, traditionnellement offerte aux mariages : pâte levée riche en beurre et en œufs, parfumée à la fleur d’oranger et à l’eau-de-vie, à la mie filante.","cat":"Dessert","diff":"medium","prep":40,"cook":35,"serv":10,"reference":"https://fr.wikipedia.org/wiki/Brioche_vendéenne","ing":[["Farine T45",500,"g",null],["Levure boulangère fraîche",20,"g",null],["Œufs",4,null,null],["Beurre mou",150,"g",null],["Sucre",80,"g",null],["Crème fraîche",50,"g",null],["Lait tiède",50,"ml",null],["Eau de fleur d’oranger",2,"c. à soupe",null],["Eau-de-vie ou rhum",2,"c. à soupe",null],["Sel",1,"c. à thé",null],["Jaune d’œuf",1,null,"pour la dorure"]],"steps":["Délayer la levure dans le lait tiède, puis pétrir avec la farine, le sucre, le sel, les œufs, la crème et les parfums 10 minutes.","Incorporer le beurre mou petit à petit jusqu’à ce que la pâte soit lisse et se décolle des parois.","Laisser lever 2 heures, puis une nuit au réfrigérateur.","Diviser en trois boudins, les tresser et déposer sur une plaque; laisser lever 1 h 30.","Dorer au jaune d’œuf et cuire 30 à 35 minutes à 170 °C."],"photo":{"file":"File:Brioche vendéenne.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/3/31/Brioche_vend%C3%A9enne.jpg","page":"https://commons.wikimedia.org/wiki/File:Brioche_vend%C3%A9enne.jpg","author":"Thomon","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"prefou-vendeen","country":"FR","place":{"slug":"fr-vendee","name":"Vendée","type":"region","lat":46.67,"lng":-1.43,"summary":"Département atlantique des Pays de la Loire : brioche vendéenne, préfou, mogettes et jambon de Vendée."},"original":"Préfou","title":"Préfou vendéen (pain à l’ail et au beurre)","en":"Vendée préfou (garlic butter bread)","es":"Préfou de la Vendée (pan con mantequilla de ajo)","desc":"Pain plat de Vendée, autrefois cuit à l’entrée du four pour en tester la chaleur : la mie est fendue et garnie d’un beurre à l’ail et au persil, puis le pain est réchauffé pour l’apéritif.","cat":"Street food","diff":"easy","prep":20,"cook":15,"serv":6,"reference":"https://fr.wikipedia.org/wiki/Préfou","ing":[["Pâte à pain",500,"g","ou une baguette précuite"],["Beurre demi-sel mou",125,"g",null],["Ail",5,"gousses","très finement hachées"],["Persil plat",2,"c. à soupe","haché"],["Poivre",0.5,"c. à thé",null]],"steps":["Façonner la pâte en un pain plat et allongé et le cuire 15 minutes à 230 °C; laisser tiédir.","Écraser le beurre mou avec l’ail, le persil et le poivre.","Fendre le pain en biais tous les 3 cm sans le couper complètement.","Garnir chaque entaille de beurre à l’ail.","Réchauffer 8 à 10 minutes à 200 °C et servir chaud à l’apéritif."],"photo":{"file":"File:Préfou.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/e/e2/Pr%C3%A9fou.jpg","page":"https://commons.wikimedia.org/wiki/File:Pr%C3%A9fou.jpg","author":"Thomon","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}}]$batch$::jsonb);
